SELECT p.gender, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version, i.careunit, i.los, c.charlson_comorbidity_score, COUNT(d.icd_code) AS comorbidity_count, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, (SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(p.subject_id), 0)) * 100 AS mortality_percentage, (SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(p.subject_id), 0)) * 100 - (COUNT(d.icd_code) * 100) AS mortality_percentage_without_comorbidities FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.hadm_id = d.hadm_id JOIN icustays i ON a.hadm_id = i.subject_id JOIN charlson c ON c.charlson_comorbidity_score BETWEEN 3 AND 5 WHERE p.gender = 'M' AND p.anchor_year = 43 AND p.anchor_year_group BETWEEN 38 AND 48 AND d.icd_code = '41508' AND d.icd_version = '4' AND i.los BETWEEN 1 AND 7 AND length(c.charlson_comorbidity_score::text) = 1 GROUP BY p.gender, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version, i.careunit, i.los, c.charlson_comorbidity_score ORDER BY p.gender, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version, i.careunit, i.los, c.charlson_comorbidity_score NULLS LAST;